{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE snitch_db.maplemonk.Product_info as ( WITH master AS ( SELECT *, CASE WHEN category IN (\'Shirt\', \'Shirts\') THEN \'Shirts\' WHEN category = \'Denim\' THEN \'Jeans\' ELSE category END AS new_category, CURRENT_DATE - 1 AS master_date FROM snitch_db.maplemonk.availability_master_v2 ), metafields_data AS ( SELECT sku_group, id, price, product_name, product_type, occassion, print_design, collar AS meta_collar, material, sleeve_type, fit, style, color, closure, length, designs FROM snitch_db.maplemonk.metafields_data ), sales AS ( SELECT DATE AS date_wise, category, sku_group, SUM(IFNULL(total_sales, 0)) AS total_sales, SUM(IFNULL(total_quant, 0)) AS total_quant FROM snitch_db.maplemonk.category_visibility GROUP BY 1, 2, 3 ), clicks AS ( SELECT ga_date, sku_group, SUM(IFNULL(clicks, 0)) AS clicks FROM snitch_db.maplemonk.clicks_itemid GROUP BY 1, 2 ), productid AS ( SELECT sku_group, id, price, status FROM ( SELECT DISTINCT a.id, REVERSE(SUBSTRING(REVERSE(b.sku), CHARINDEX(\'-\', REVERSE(b.sku)) + 1)) AS SKU_GROUP, TO_TIMESTAMP(REPLACE(b.updated_at, \'\"\', \'\')) AS updated_at, ROW_NUMBER() OVER (PARTITION BY SKU_GROUP ORDER BY b.updated_at DESC) AS rw, b.price AS price, status FROM snitch_db.MAPLEMONK.SHOPIFY_ALL_PRODUCTS a LEFT JOIN snitch_db.maplemonk.shopifyindia_product_variants b ON a.id = b.product_id ) WHERE rw = 1 ) SELECT COALESCE(sales.date_wise, master.master_date, clicks.ga_date) AS date_wise, COALESCE(sales.sku_group, master.sku_group, clicks.sku_group) AS sku_group, master.new_category, master.ID, master.PRICE, master.PRODUCT_NAME, master.CATEGORY, master.FINAL_ROS, master.TOTAL_EOQ, master.AVAILABLE_UNITS, master.ORDER_POINT, master.NATURAL_ROS, master.SALES_LAST_7_DAYS, master.SALES_LAST_15_DAYS, master.SALES_LAST_30_DAYS, master.SKU_CLASS, master.SELLABLE_INVENTORY, master.XS_UNITS, master.S_UNITS, master.M_UNITS, master.L_UNITS, master.XL_UNITS, master.XXL_UNITS, master.XL3_UNITS, master.XL4_UNITS, master.XL5_UNITS, master.XL6_UNITS, master.NUM_SIZE_AVAILABLE, master.STATUS, master.LIVE_DATE, total_sales, total_quant, meta.product_type, meta.occassion, meta.print_design, meta.meta_collar, -- Updated to specify metafields collar meta.material, meta.sleeve_type, meta.fit, meta.style, meta.color, meta.closure, meta.length, productid.id AS product_id, clicks.clicks, -- Design categorization CASE WHEN LOWER(meta.print_design) LIKE \'%checks%\' THEN \'Checks\' WHEN LOWER(meta.print_design) LIKE \'%animal%\' THEN \'Animal Print\' WHEN LOWER(meta.print_design) LIKE \'%embroid%\' THEN \'Embroided\' WHEN LOWER(meta.print_design) LIKE \'%floral%\' THEN \'Floral\' WHEN LOWER(meta.print_design) LIKE \'%graphic%\' THEN \'Graphic Print\' WHEN LOWER(meta.print_design) LIKE \'%embellished%\' THEN \'Embellished\' WHEN LOWER(meta.print_design) LIKE \'%plain%\' THEN \'Solid\' WHEN LOWER(meta.print_design) LIKE \'%solid%\' THEN \'Solid\' WHEN LOWER(meta.print_design) LIKE \'%printed%\' THEN \'Printed\' WHEN LOWER(meta.print_design) LIKE \'%self%\' THEN \'Self Design\' WHEN LOWER(meta.print_design) LIKE \'%stripe%\' THEN \'Stripes\' WHEN LOWER(meta.print_design) LIKE \'%crochet%\' THEN \'Crochet\' WHEN LOWER(meta.print_design) LIKE \'%polka%\' THEN \'Polka Dots\' WHEN LOWER(meta.print_design) LIKE \'%geometric%\' THEN \'Geometric\' WHEN LOWER(meta.print_design) LIKE \'%tie &%\' THEN \'Tie & Dye\' WHEN LOWER(meta.print_design) LIKE \'%textured%\' THEN \'Textured\' WHEN meta.print_design IS NULL THEN \'Null\' ELSE \'Others\' END AS Designs, -- Collar categorization CASE WHEN LOWER(meta.meta_collar) LIKE \'%cuban%\' THEN \'Cuban\' WHEN LOWER(meta.meta_collar) LIKE \'%crew%\' THEN \'Round\' WHEN LOWER(meta.meta_collar) LIKE \'%round%\' THEN \'Round\' WHEN LOWER(meta.meta_collar) LIKE \'%polo%\' THEN \'Polo\' WHEN LOWER(meta.meta_collar) LIKE \'%high neck%\' THEN \'High Neck\' WHEN LOWER(meta.meta_collar) LIKE \'%spread%\' THEN \'Spread\' WHEN LOWER(meta.meta_collar) LIKE \'%button down%\' THEN \'Button Down\' WHEN LOWER(meta.meta_collar) LIKE \'%mandarin%\' THEN \'Mandarin\' WHEN LOWER(meta.meta_collar) LIKE \'%baseball%\' THEN \'Baseball\' WHEN LOWER(meta.meta_collar) LIKE \'%classic%\' THEN \'Classic\' WHEN LOWER(meta.meta_collar) LIKE \'%shawl%\' THEN \'Shawl\' WHEN LOWER(meta.meta_collar) LIKE \'%hooded%\' THEN \'Hooded\' WHEN LOWER(meta.meta_collar) LIKE \'%mock%\' THEN \'Round\' WHEN LOWER(meta.meta_collar) LIKE \'%turtleneck%\' THEN \'Turtle Neck\' WHEN LOWER(meta.meta_collar) LIKE \'%camp%\' THEN \'Cuban\' WHEN meta.meta_collar IS NULL THEN \'Null\' ELSE \'Others\' END AS Collar_New, -- Material categorization CASE WHEN LOWER(meta.material) LIKE \'%cotton%\' THEN \'Cotton\' WHEN LOWER(meta.material) LIKE \'%poly%\' THEN \'Polyester\' WHEN LOWER(meta.material) LIKE \'%rayon%\' THEN \'Rayon\' WHEN LOWER(meta.material) LIKE \'%linen%\' THEN \'Linen\' WHEN LOWER(meta.material) LIKE \'%terry%\' THEN \'Terry\' WHEN LOWER(meta.material) LIKE \'%modal%\' THEN \'Modal\' WHEN LOWER(meta.material) LIKE \'%tencel%\' THEN \'Tencel\' WHEN LOWER(meta.material) LIKE \'%nylon%\' THEN \'Nylon\' WHEN LOWER(meta.material) LIKE \'%tencil%\' THEN \'Tencil\' WHEN LOWER(meta.material) LIKE \'%steel%\' THEN \'Stainless Steel\' WHEN meta.material IS NULL THEN \'Null\' ELSE \'Others\' END AS Material_New FROM master LEFT JOIN metafields_data meta ON LOWER(master.id) = LOWER(meta.id) FULL OUTER JOIN sales ON LOWER(master.sku_group) = LOWER(sales.sku_group) AND (master.master_date) = (sales.date_wise) LEFT JOIN productid ON LOWER(master.sku_group) = LOWER(productid.sku_group) FULL OUTER JOIN clicks ON LOWER(COALESCE(sales.sku_group, master.sku_group)) = LOWER(clicks.sku_group) AND (COALESCE(sales.date_wise, master.master_date)) = (clicks.ga_date) );",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from snitch_db.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            